sql.where:
app_id = #{q.appId}
 AND platform = #{q.platform}
 AND kind = #{q.kind}
 AND app_version = #{q.appVersion}
 AND device_id = #{q.deviceId}
 AND brand = #{q.brand}
 AND model = #{q.model}
 AND name = #{q.name}
 AND occurred_at BETWEEN #{q.beginTime} AND #{q.endTime}

    AND (name LIKE CONCAT('%',#{q.keyword},'%') OR label LIKE CONCAT('%',#{q.keyword},'%')
         OR page_url LIKE CONCAT('%',#{q.keyword},'%'))

mapper.select:
SELECT  FROM logan_behavior

ORDER BY occurred_at DESC
 LIMIT #{q.offset}, #{q.limit}
 LIMIT #{q.limit}

SELECT  FROM logan_behavior
WHERE app_id = #{appId} AND device_id = #{deviceId}
  AND occurred_at BETWEEN #{beginTime} AND #{endTime}
ORDER BY occurred_at DESC LIMIT #{limit}

SELECT COUNT(*) AS events, COUNT(DISTINCT device_id) AS devices
FROM logan_behavior

    app_id = #{appId}
    AND occurred_at BETWEEN #{beginTime} AND #{endTime}
     AND platform = #{platform}
     AND app_version = #{appVersion}

SELECT kind AS kind, name AS name, COUNT(*) AS events, COUNT(DISTINCT device_id) AS devices,
       MAX(occurred_at) AS lastTime
FROM logan_behavior

    app_id = #{appId}
    AND name IS NOT NULL AND name != ''
    AND occurred_at BETWEEN #{beginTime} AND #{endTime}
     AND kind = #{kind}
     AND platform = #{platform}

GROUP BY kind, name
ORDER BY events DESC
LIMIT #{limit}
